// SPDX-License-Identifier: MIT
pragma cashscript ^0.10.0;

contract UserDeposit(bytes20 userPubKeyHash) {
    /**
     * @notice Withdraw _all_ funds back to the user’s wallet.
     * @param userSig     Signature by the user.
     * @param userPubKey  The user’s pubkey (must hash to the saved pubKeyHash).
     */
    function withdraw(sig userSig, pubkey userPubKey) {
        require(checkSig(userSig, userPubKey));
        require(hash160(userPubKey) == userPubKeyHash);
    }

    /**
     * @notice Deduct a per-message fee.
     * @param userSig        Signature by the user.
     * @param feeAmount      Fee in satoshis to send to the chat room.
     * @param chatRoomScript The chat room’s locking bytecode.
     * @param userPubKey     The user’s pubkey (must hash to saved hash).
     */
    function deductFee(
        sig userSig,
        int feeAmount,
        bytes chatRoomScript,
        pubkey userPubKey
    ) {
        // 1) Auth
        require(checkSig(userSig, userPubKey));
        require(hash160(userPubKey) == userPubKeyHash);

        // 2) First output is exactly the fee to the ChatRoom
        require(tx.outputs[0].value == feeAmount);
        require(tx.outputs[0].lockingBytecode == chatRoomScript);

        // 3) Second output must re‐lock the remainder back to _this_ contract
        require(tx.outputs[1].lockingBytecode == this.activeBytecode);
    }
}
